  "inlineSchema": "// Syria Market - Database Schema\n// Using SQLite for easy local setup. Switch provider to \"postgresql\" for production.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// Note: SQLite doesn't support native enum types in Prisma, so Role, ListingStatus,\n// and ListingCondition are plain strings below, validated in application code instead.\n// Allowed values — Role: USER | ADMIN\n// ListingStatus: ACTIVE | SOLD | PENDING_REVIEW | REJECTED | HIDDEN\n// ListingCondition: NEW | LIKE_NEW | GOOD | FAIR | FOR_PARTS\n\nmodel User {\n  id           Int      @id @default(autoincrement())\n  name         String\n  email        String   @unique\n  phone        String   @unique\n  passwordHash String\n  avatarUrl    String?\n  city         String?\n  role         String   @default(\"USER\")\n  isVerified   Boolean  @default(false)\n  isBanned     Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  listings        Listing[]\n  sentMessages    Message[]      @relation(\"SentMessages\")\n  conversations1  Conversation[] @relation(\"Buyer\")\n  conversations2  Conversation[] @relation(\"Seller\")\n  reviewsGiven    Review[]       @relation(\"ReviewAuthor\")\n  reviewsReceived Review[]       @relation(\"ReviewTarget\")\n  favorites       Favorite[]\n  reports         Report[]       @relation(\"ReportAuthor\")\n}\n\nmodel Category {\n  id       Int        @id @default(autoincrement())\n  nameAr   String\n  nameEn   String\n  slug     String     @unique\n  icon     String?\n  parentId Int?\n  parent   Category?  @relation(\"SubCategories\", fields: [parentId], references: [id])\n  children Category[] @relation(\"SubCategories\")\n  listings Listing[]\n}\n\nmodel Listing {\n  id          Int      @id @default(autoincrement())\n  title       String\n  description String\n  price       Float\n  currency    String   @default(\"SYP\") // SYP or USD\n  condition   String   @default(\"GOOD\")\n  status      String   @default(\"ACTIVE\")\n  city        String\n  negotiable  Boolean  @default(true)\n  viewCount   Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  sellerId   Int\n  seller     User     @relation(fields: [sellerId], references: [id])\n  categoryId Int\n  category   Category @relation(fields: [categoryId], references: [id])\n\n  images        ListingImage[]\n  conversations Conversation[]\n  favorites     Favorite[]\n  reports       Report[]\n}\n\nmodel ListingImage {\n  id        Int     @id @default(autoincrement())\n  url       String\n  listingId Int\n  listing   Listing @relation(fields: [listingId], references: [id], onDelete: Cascade)\n}\n\nmodel Conversation {\n  id        Int       @id @default(autoincrement())\n  listingId Int\n  listing   Listing   @relation(fields: [listingId], references: [id])\n  buyerId   Int\n  buyer     User      @relation(\"Buyer\", fields: [buyerId], references: [id])\n  sellerId  Int\n  seller    User      @relation(\"Seller\", fields: [sellerId], references: [id])\n  createdAt DateTime  @default(now())\n  messages  Message[]\n\n  @@unique([listingId, buyerId])\n}\n\nmodel Message {\n  id             Int          @id @default(autoincrement())\n  conversationId Int\n  conversation   Conversation @relation(fields: [conversationId], references: [id])\n  senderId       Int\n  sender         User         @relation(\"SentMessages\", fields: [senderId], references: [id])\n  body           String\n  isRead         Boolean      @default(false)\n  createdAt      DateTime     @default(now())\n}\n\nmodel Review {\n  id        Int      @id @default(autoincrement())\n  rating    Int // 1-5\n  comment   String?\n  authorId  Int\n  author    User     @relation(\"ReviewAuthor\", fields: [authorId], references: [id])\n  targetId  Int\n  target    User     @relation(\"ReviewTarget\", fields: [targetId], references: [id])\n  createdAt DateTime @default(now())\n\n  @@unique([authorId, targetId])\n}\n\nmodel Favorite {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  user      User     @relation(fields: [userId], references: [id])\n  listingId Int\n  listing   Listing  @relation(fields: [listingId], references: [id])\n  createdAt DateTime @default(now())\n\n  @@unique([userId, listingId])\n}\n\nmodel Report {\n  id        Int      @id @default(autoincrement())\n  reason    String\n  authorId  Int\n  author    User     @relation(\"ReportAuthor\", fields: [authorId], references: [id])\n  listingId Int\n  listing   Listing  @relation(fields: [listingId], references: [id])\n  createdAt DateTime @default(now())\n}\n",
